    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Nem nướng cuốn rau sống chấm tương béo, ngồi ăn chậm rãi mới đã."
    },
    {
      "poi_id": "p215",
      "kind": "activity",
      "must_do_id": null,
      "note": "Đồi thoai thoải, hoa và cây cảnh xếp lớp, đứng đây ngắm nắng chiều buông."
    },
    {
      "poi_id": "p158",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bia thủ công mát lạnh, món nhắm tinh tế, tối ở Đà Lạt nên ngồi đây."
    }
  ]
}
